# Substrate §3.4 — Capability Registry (persistent).
# Loads capabilities.json on first access; lazy-seeds the built-in
# catalog if empty; writes back on any mutation. If the envelope
# carries intent.capability, fold the registered scopes into env["scopes"].
try:
    from proactive.persistence import read_json, write_json
except ImportError:
    import sys, os
    sys.path.insert(0, os.path.join(os.getcwd(), 'app'))
    from proactive.persistence import read_json, write_json

env  = dict(input) if isinstance(input, dict) else {"raw": input}
caps = variables.get("capabilities")
if caps is None:
    caps = read_json("capabilities", default={})
    variables["capabilities"] = caps

mutated = False
if not caps:
    caps["core.notify"] = {
        "name":          "core.notify",
        "purpose":       "Surface a UI notification to the user",
        "scopes":        ["read-only"],
        "latency_tier":  "interactive",
        "cost_estimate": 0.0,
    }
    caps["core.send_email"] = {
        "name":          "core.send_email",
        "purpose":       "Send an outbound email",
        "scopes":        ["write", "external-network", "affects-third-party"],
        "latency_tier":  "responsive",
        "cost_estimate": 0.001,
    }
    caps["core.transfer_funds"] = {
        "name":          "core.transfer_funds",
        "purpose":       "Initiate a money transfer",
        "scopes":        ["spends-money", "write", "affects-third-party"],
        "latency_tier":  "responsive",
        "cost_estimate": 0.5,
    }
    mutated = True

if mutated:
    write_json("capabilities", caps)

intent   = env.get("intent") or {}
cap_name = intent.get("capability")
if cap_name and cap_name in caps:
    cap = caps[cap_name]
    env["resolved_capability"] = {
        "name":         cap_name,
        "scopes":       cap["scopes"],
        "latency_tier": cap["latency_tier"],
    }
    env["scopes"] = sorted(set(list(env.get("scopes", [])) + list(cap["scopes"])))
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": cap_name})
else:
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": None})
output = env

# Substrate §3.5 — Governor (M3.2 coordination — reads adversarial flags).
# Adds two rules over the Phase-1 stub:
#   (a) intent + injection_hits → deny  (untrusted-source actuation refused)
#   (b) intent + very-low confidence → consent_required
env    = dict(input) if isinstance(input, dict) else {"raw": input}
scopes = list(env.get("scopes", ["read-only"]))
conf   = float(env.get("confidence", 1.0))

HIGH_STAKE = {"spends-money", "impersonates-user", "affects-third-party"}
WRITE      = {"write"}

intent         = env.get("intent")
injection_hits = ((env.get("untrusted_content") or {}).get("injection_hits") or [])

if intent and injection_hits:
    decision, reason = "deny", "adversarial input on actuation — refused"
elif any(s in HIGH_STAKE for s in scopes):
    decision, reason = "consent_required", "high-stake scope present"
elif any(s in WRITE for s in scopes) and conf < 0.85:
    decision, reason = "consent_required", "write at low confidence"
elif intent and conf < 0.40:
    decision, reason = "consent_required", "intent at very low confidence"
else:
    decision, reason = "allow", "low-class action"

env["governor_verdict"] = {
    "decision":   decision,
    "reason":     reason,
    "scopes":     scopes,
    "confidence": conf,
}
output = env
